/* C API of the Rust port of `spmreturn.c`, generated by rust-anything. */
#ifndef SPMRETURN_RS_H
#define SPMRETURN_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

double RetWater(int hot, int ttype, double mdot, double tsup, double tret, double target, double retsp, double mint, double maxt);
double SysNode(int ctrl, double ref, double lowref, double highref, double splow, double sphigh);

/* The same functions under `rust_anything_` names, for shadow runs. */
double rust_anything_RetWater(int hot, int ttype, double mdot, double tsup, double tret, double target, double retsp, double mint, double maxt);
double rust_anything_SysNode(int ctrl, double ref, double lowref, double highref, double splow, double sphigh);

#endif /* SPMRETURN_RS_H */
